import {DAYS,TASKS,BUDGET_KEYS} from './data.js';
import {config} from './config.js';
import {escapeHTML as esc,cleanState,totalBudget,maps,nextRevision} from './core.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const euro=new Intl.NumberFormat('de-AT',{style:'currency',currency:'EUR'});
const df=new Intl.DateTimeFormat('de-AT',{day:'2-digit',month:'2-digit',year:'numeric'});
let client,context=null,plan=cleanState({}),revision=null,votes=[],filter='all',selectedDay=1,dirty=false,saving=false,toastTimer;
const labels={flight:'Flug pro Person (€)',stay:'Unterkünfte gesamt / 9 Nächte (€)',car:'Mietwagen gesamt (€)',road:'Sprit, Parken & Maut gesamt (€)',food:'Essen pro Person / Tag (€)',fun:'Eintritte pro Person (€)',extra:'Reserve für alle (€)'};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6000);}
function date(offset=0){if(!plan.start)return '';const d=new Date(plan.start+'T12:00:00');d.setDate(d.getDate()+offset);return df.format(d);}
function renderDays(){
 $('#itinerary').innerHTML=DAYS.map(d=>{const mine=context&&votes.some(v=>v.day===d.day&&v.member_key===context.me);return `<article class="day-card" data-region="${d.region}" ${filter!=='all'&&filter!==d.region?'hidden':''}><div class="day-banner"><strong>${String(d.day).padStart(2,'0')}</strong><span>${d.region.toUpperCase()}<br>${date(d.day-1)||'ROADTRIP DAY'}</span></div><div class="day-body"><h3>${esc(d.city)}</h3><p class="subtitle">${esc(d.subtitle)}</p><p class="day-text">${esc(d.text)}</p><div class="day-meta"><span>↗ ${esc(d.drive)}</span><span>⌂ ${esc(d.sleep)}</span></div><div class="day-actions"><button data-day="${d.day}">Tag im Detail ↗</button><button class="vote-button" data-vote="${d.day}" aria-pressed="${!!mine}" aria-label="Tag ${d.day} als Favorit markieren">${mine?'♥':'♡'} ${votes.filter(v=>v.day===d.day).length||'Merken'}</button></div></div></article>`;}).join('');
}
function showDay(n){const d=DAYS.find(x=>x.day===n);if(!d)return;selectedDay=n;$('#day-detail').innerHTML=`<p class="eyebrow">TAG ${String(n).padStart(2,'0')} / ${d.region.toUpperCase()}</p><h2 id="day-title">${esc(d.city)}</h2><p class="subtitle">${esc(d.subtitle)}</p><ul class="day-schedule">${d.schedule.map(([when,what])=>`<li><strong>${esc(when)}</strong><p>${esc(what)}</p></li>`).join('')}</ul><p class="detail-tip">${esc(d.tip)}</p><div class="dialog-links"><a href="${esc(maps(d))}" target="_blank" rel="noopener noreferrer">In Google Maps ↗</a><a href="${esc(d.source)}" target="_blank" rel="noopener noreferrer">${esc(d.sourceLabel)} ↗</a></div><p class="detail-meta">${esc(d.drive)} · ${esc(d.distance)}<br>Übernachtung: ${esc(d.sleep)}</p>`;$('#day-dialog').setAttribute('aria-labelledby','day-title');$('#prev-day').disabled=n===1;$('#next-day').disabled=n===10;if(!$('#day-dialog').open)$('#day-dialog').showModal();$('#day-dialog').scrollTop=0;}
function route(scroll=true){let [page,query='']=(location.hash.slice(1)||'reiseinfos').split('?');page=({uebersicht:'reiseinfos',route:'programm',crew:'gruppe'})[page]||page;const view=['reiseinfos','programm','gruppe','planung'].includes(page)?page:'reiseinfos';if($('#day-dialog').open)$('#day-dialog').close();$$('[data-view]').forEach(x=>x.hidden=x.dataset.view!==view);$$('[data-nav]').forEach(x=>{if(x.dataset.nav===view)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current');});document.title=({reiseinfos:'Howdy Texas',programm:'Unser Programm',gruppe:'Unsere Gruppe',planung:'Unsere Planung'})[view]+' · Roadtrip';if(scroll)document.querySelector('.view-nav').scrollIntoView({behavior:'instant',block:'start'});const day=Number(new URLSearchParams(query).get('day'));if(view==='programm'&&day>=1&&day<=10)showDay(day);}
function openLogin(){ $('#login-error').textContent='';$('#login-submit').disabled=config.backendReady&&!client;$('#login-form').hidden=!config.backendReady;$('#setup-message').hidden=config.backendReady;$('#login-intro').hidden=!config.backendReady;$('#login-dialog').showModal();}
function budget(){const b=readForm().budget,n=BUDGET_KEYS.filter(k=>b[k]!==null).length,t=totalBudget(b);$('#budget-total').textContent=n?euro.format(t):'–';$('#budget-person').textContent=n?euro.format(t/4):'–';$('#budget-hint').textContent=n?`${n}/7 Kostenfelder ausgefüllt. ${n<7?'Unvollständige Schätzung; leere Felder fehlen noch.':'Eigene Schätzung, keine bestätigten Angebote.'}`:'Eigene Schätzwerte eintragen. Berechnung für 4 Personen und 10 Tage.';}
function readForm(){const form=$('#plan-form'),raw={start:form.elements.start.value,note:form.elements.note.value,tasks:{},budget:{}};TASKS.forEach(([id])=>raw.tasks[id]=form.elements['task-'+id].checked);BUDGET_KEYS.forEach(k=>{const el=form.elements[k];raw.budget[k]=el.value===''||!el.validity.valid?null:Number(el.value);});return cleanState(raw);}
function renderPlan(){const f=$('#plan-form');f.elements.start.value=plan.start;f.elements.note.value=plan.note;TASKS.forEach(([id])=>f.elements['task-'+id].checked=plan.tasks[id]);BUDGET_KEYS.forEach(k=>f.elements[k].value=plan.budget[k]??'');$('#date-summary').textContent=plan.start?date():'Noch offen';$('#date-detail').textContent=plan.start?`${date()} bis ${date(9)} · gemeinsamer Terminvorschlag.`:'Terminvorschlag, noch keine Buchung.';dirty=false;$('.sync-bar').dataset.dirty='false';budget();renderDays();}
function renderGroup(){if(!context)return;$('#people').innerHTML=context.people.map(p=>`<article class="person"><div class="avatar" aria-hidden="true">${esc(p.name.split(' ').map(x=>x[0]).join(''))}</div><h3>${esc(p.name)}</h3><small>${p.key===context.me?'Du bist angemeldet':'Teil unserer Crew'}</small></article>`).join('');$('#group-votes').innerHTML=DAYS.filter(d=>votes.some(v=>v.day===d.day)).map(d=>`<div class="vote-summary"><b>Tag ${d.day} · ${esc(d.city)}</b><small>${votes.filter(v=>v.day===d.day).map(v=>esc(context.people.find(p=>p.key===v.member_key)?.name||'')).join(', ')}</small></div>`).join('')||'<p class="muted">Noch keine Favoriten. Im Programm auf das Herz beim Lieblingstag klicken.</p>';}
function clearPrivate(){context=null;votes=[];revision=null;plan=cleanState({});dirty=false;$$('.protected').forEach(x=>x.hidden=true);$$('.private-gate').forEach(x=>x.hidden=false);$('#whoami').textContent='';$('#account-button').textContent='Anmelden ↗';$('#people').replaceChildren();$('#group-votes').replaceChildren();renderPlan();}
async function loadPlan(){const {data,error}=await client.from('howdy_plan').select('data,revision,updated_at').eq('id',1).single();if(error||!data)throw Error('Planung konnte nicht geladen werden. Bitte erneut versuchen.');plan=cleanState(data.data);revision=data.revision;renderPlan();$('#sync-status').textContent='Gemeinsamer Stand · '+new Date(data.updated_at).toLocaleString('de-AT');}
async function loadVotes(){const {data,error}=await client.from('howdy_votes').select('member_key,day');if(error)throw Error('Favoriten konnten nicht geladen werden.');votes=data||[];renderDays();renderGroup();}
async function enter(){const result=await client.rpc('howdy_context');if(result.error)throw Error('Gruppenbereich momentan nicht erreichbar.');if(!result.data?.me)throw Error('Dieser Zugang gehört nicht zur Texas-Reisegruppe.');context=result.data;try{await Promise.all([loadPlan(),loadVotes()]);}catch(e){clearPrivate();throw e;}$$('.protected').forEach(x=>x.hidden=false);$$('.private-gate').forEach(x=>x.hidden=true);$('#whoami').textContent=context.name;$('#account-button').textContent='Abmelden';renderGroup();}
async function invoke(body){const r=await client.functions.invoke(config.functionName,{body});if(r.error){let msg='Dienst momentan nicht erreichbar.';try{msg=(await r.error.context.json()).error||msg;}catch{}throw Error(msg);}if(!r.data?.ok)throw Error(r.data?.error||'Anmeldung fehlgeschlagen.');return r.data;}
async function signIn(name,code){if(!client)throw Error('Anmeldung wird noch geladen. Bitte kurz warten.');let {data}=await client.auth.getSession();if(!data.session){const a=await client.auth.signInAnonymously();if(a.error)throw Error('Anmeldung konnte nicht gestartet werden.');}await invoke({name,code});await enter();}
$('#task-list').innerHTML=TASKS.map(([id,title,note])=>`<label class="task-label"><input type="checkbox" name="task-${id}"><span><b>${esc(title)}</b><small>${esc(note)}</small></span></label>`).join('');
$('#budget-inputs').innerHTML=BUDGET_KEYS.map(k=>`<label>${labels[k]}<input type="number" name="${k}" min="0" max="100000" step="0.01" inputmode="decimal"></label>`).join('');
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>$('#'+b.dataset.close).close()));$$('[data-open-login]').forEach(b=>b.addEventListener('click',openLogin));
$('#show-password').addEventListener('change',e=>$('#login-code').type=e.target.checked?'text':'password');
$('#login-dialog').addEventListener('close',()=>{$('#login-code').value='';$('#login-code').type='password';$('#show-password').checked=false;});
$('#account-button').addEventListener('click',async()=>{if(!context){openLogin();return;}if(dirty&&!confirm('Ungespeicherte Änderungen verwerfen und abmelden?'))return;const revoked=await client.rpc('howdy_logout');await client.auth.signOut({scope:'local'});clearPrivate();toast(revoked.error?'Lokal abgemeldet. Die Serversitzung konnte gerade nicht beendet werden.':'Abgemeldet.');});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();if(!config.backendReady)return;$('#login-submit').disabled=true;$('#login-error').textContent='';try{await signIn($('#login-name').value,$('#login-code').value);$('#login-dialog').close();toast('Howdy, '+context.name.split(' ')[0]+'!');}catch(err){clearPrivate();$('#login-error').textContent=err.message;}finally{$('#login-submit').disabled=false;}});
$('#itinerary').addEventListener('click',async e=>{const detail=e.target.closest('[data-day]');if(detail){showDay(Number(detail.dataset.day));return;}const b=e.target.closest('[data-vote]');if(!b)return;if(!context){openLogin();return;}b.disabled=true;try{const day=Number(b.dataset.vote),mine=votes.some(v=>v.day===day&&v.member_key===context.me);const r=mine?await client.from('howdy_votes').delete().eq('member_key',context.me).eq('day',day):await client.from('howdy_votes').insert({member_key:context.me,day});if(r.error)throw Error('Favorit wurde nicht gespeichert.');await loadVotes();}catch(err){toast(err.message);}finally{b.disabled=false;}});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderDays();}));
$('#prev-day').addEventListener('click',()=>showDay(selectedDay-1));$('#next-day').addEventListener('click',()=>showDay(selectedDay+1));$('#print-route').addEventListener('click',()=>window.print());
$('#plan-form').addEventListener('input',()=>{dirty=true;$('.sync-bar').dataset.dirty='true';$('#sync-status').textContent='Ungespeicherte Änderungen';budget();});
$('#plan-form').addEventListener('submit',async e=>{e.preventDefault();if(!context||saving||revision===null)return;saving=true;$('#save-plan').disabled=true;const draft=readForm();try{const r=await client.from('howdy_plan').update({data:draft,revision:nextRevision(revision)}).eq('id',1).eq('revision',revision).select('revision,updated_at');if(r.error)throw Error('Speichern fehlgeschlagen. Deine Eingaben bleiben stehen.');if(r.data?.length!==1)throw Error('Inzwischen hat jemand den Plan geändert. Deine Eingaben bleiben stehen. Kopiere sie bei Bedarf und lade den neuen Stand.');plan=draft;revision=r.data[0].revision;renderPlan();$('#sync-status').textContent='Für alle gespeichert · '+new Date(r.data[0].updated_at).toLocaleString('de-AT');toast('Gemeinsame Planung gespeichert.');}catch(err){$('#sync-status').textContent=err.message;toast(err.message);}finally{saving=false;$('#save-plan').disabled=false;}});
$('#reload-plan').addEventListener('click',async()=>{if(dirty&&!confirm('Deine ungespeicherten Eingaben verwerfen und den gemeinsamen Stand laden?'))return;try{await Promise.all([loadPlan(),loadVotes()]);}catch(e){toast(e.message);}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});window.addEventListener('hashchange',()=>route());
renderPlan();route(false);
if(config.backendReady){try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.4');client=createClient(config.url,config.publicKey,{auth:{storageKey:'howdy-texas-auth-v2',detectSessionInUrl:false,persistSession:true,autoRefreshToken:true}});$('#login-submit').disabled=false;client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT')clearPrivate();});const {data}=await client.auth.getSession();if(data.session)await enter();}catch(err){clearPrivate();toast(err.message||'Anmeldung momentan nicht erreichbar.');}}


